parameters.jsCode:
/**
 * Give every notification the same shape and a consistent severity.
 *
 * The correlation id is always included: it is what turns "something happened"
 * into a trace an operator can follow through Adericel, the worker and the
 * external system.
 */
const input = $input.first().json;
const severity = ['urgent', 'attention', 'info'].includes(input.severity) ? input.severity : 'info';
const config = $('Configuration').first().json;

const prefix = severity === 'urgent' ? '[URGENT] ' : severity === 'attention' ? '[Attention] ' : '';

return [
  {
    json: {
      severity,
      subject: prefix + (input.subject || 'Adericel notification'),
      message:
        (input.message || '') +
        '\n\n— Adericel' +
        (input.organisationId ? '\nOrganisation: ' + input.organisationId : '') +
        (input.correlationId ? '\nCorrelation: ' + input.correlationId : ''),
      organisationId: input.organisationId || null,
      correlationId: input.correlationId || $execution.id,
      notifyEmail: config.notifyEmail,
      notifyWebhookUrl: config.notifyWebhookUrl,
    },
  },
];

/**
 * Turn an n8n execution error into something an operator can act on.
 *
 * The correlation id is recovered from the failing execution's data where
 * possible, so the failure can be joined to everything else that happened in
 * that operation through Adericel's trace endpoint.
 */
const error = $input.first().json;
const execution = error.execution || {};
const workflowInfo = error.workflow || {};

const lastNode = execution.lastNodeExecuted || 'unknown node';
const message = (execution.error && execution.error.message) || 'No error message was recorded.';

let correlationId = null;
try {
  const runData = (execution.data && execution.data.resultData && execution.data.resultData.runData) || {};
  for (const nodeRuns of Object.values(runData)) {
    for (const run of nodeRuns || []) {
      const items = (run.data && run.data.main && run.data.main[0]) || [];
      for (const item of items) {
        if (item && item.json && item.json.correlationId) {
          correlationId = item.json.correlationId;
          break;
        }
      }
    }
  }
} catch {
  // The failing execution may not have produced usable data. The failure is
  // still reported; it simply cannot be joined to an Adericel trace.
}

return [
  {
    json: {
      severity: 'urgent',
      correlationId,
      subject: 'Adericel workflow failed: ' + (workflowInfo.name || 'unknown workflow'),
      message:
        'Workflow: ' + (workflowInfo.name || 'unknown') + '\n' +
        'Failed at: ' + lastNode + '\n' +
        'Execution: ' + (execution.id || 'unknown') + '\n' +
        (correlationId ? 'Correlation: ' + correlationId + '\n' : '') +
        '\n' + message +
        '\n\nNothing has been retried automatically. Adericel state is unchanged by this failure ' +
        'except where a step had already committed, which the correlation trace will show.',
      workflowName: workflowInfo.name,
      executionId: execution.id,
      failedNode: lastNode,
    },
  },
];

/**
 * Report what the assessment concluded, in the product's own vocabulary.
 *
 * Unknown is reported separately from failing throughout. Folding them together
 * would tell an MSP that a customer they cannot see is the same as a customer
 * who is failing, and those need completely different responses.
 */
const result = $input.first().json.body || {};
const summary = result.summary || {};
const counts = summary.counts || {};
const trigger = $('When called by another workflow').first().json;

return [
  {
    json: {
      organisationId: trigger.organisationId,
      correlationId: trigger.correlationId,
      controlsAssessed: result.controlsAssessed || 0,
      statesChanged: result.statesChanged || 0,
      findingsOpened: result.findingsOpened || 0,
      findingsResolved: result.findingsResolved || 0,
      state: summary.state,
      counts,
      unknownCount: counts.UNKNOWN || 0,
      failingCount: counts.NOT_SATISFIED || 0,
    },
  },
];

/**
 * Work out what kind of change this is and how loudly to say so.
 *
 * Four distinct transitions, deliberately not collapsed into "good" and "bad":
 *
 *  - deterioration  — was proven, now failing. The customer's posture changed.
 *  - visibility lost — was determinate, now unknown. Adericel stopped being able
 *    to see. Usually a collection problem, and usually ours.
 *  - improvement    — now proven. Worth recording, quietly.
 *  - visibility gained — was unknown, now determinate. Evidence arrived.
 */
const event = $input.first().json;
const payload = event.payload || {};
const previous = payload.previousState;
const current = payload.state;

const determinate = ['SATISFIED', 'PARTIALLY_SATISFIED', 'NOT_SATISFIED', 'EXCEPTED'];

let kind;
let severity;
let headline;

if (current === 'UNKNOWN' && determinate.includes(previous)) {
  kind = 'visibility-lost';
  severity = 'attention';
  headline = 'Adericel can no longer determine a control it previously could';
} else if (current === 'NOT_SATISFIED' && previous !== 'NOT_SATISFIED') {
  kind = 'deterioration';
  severity = 'urgent';
  headline = 'A control has started failing';
} else if (determinate.includes(current) && previous === 'UNKNOWN') {
  kind = 'visibility-gained';
  severity = 'info';
  headline = 'Adericel can now determine a control that was unknown';
} else if (current === 'SATISFIED') {
  kind = 'improvement';
  severity = 'info';
  headline = 'A control is now proven';
} else {
  kind = 'change';
  severity = 'info';
  headline = 'A control changed state';
}

const message =
  headline + '. ' + (payload.controlKey || payload.subjectType || 'Subject') +
  ' moved from ' + (previous || 'no previous state') + ' to ' + current + '. ' +
  (payload.rationale || '') +
  (kind === 'visibility-lost'
    ? ' This usually means a source stopped collecting or its evidence passed its freshness limit. ' +
      'It is not a statement that the customer got worse — it is a statement that Adericel stopped being able to say.'
    : '');

return [
  {
    json: {
      organisationId: event.organisationId,
      correlationId: event.correlationId,
      kind,
      severity,
      subject: 'Adericel: ' + headline,
      message,
      controlKey: payload.controlKey || null,
      previousState: previous,
      state: current,
      notifiable: kind === 'deterioration' || kind === 'visibility-lost',
    },
  },
];

/**
 * Decide whether this finding has an automatable remediation.
 *
 * The mapping from finding to fix lives in the ruleset that raised it, not
 * here. That matters: the rule author decides what an appropriate remediation
 * is, it is versioned and hashed with the rule, and this workflow cannot invent
 * a fix the rule never sanctioned.
 */
const event = $('When called by another workflow').first().json;
const findingId = event.subjectId;
const payload = event.payload || {};

const findings = ($('Read the finding').first().json.body || {}).findings || [];
const finding = findings.find((candidate) => candidate.id === findingId);

if (!finding) {
  return [{ json: { propose: false, reason: 'The finding is no longer open.', findingId } }];
}

const capabilities = ($('Read available capabilities').first().json.body || {}).capabilities || [];
const rulesets = ($('Read the rulesets').first().json.body || {}).engineRulesets || [];

const controlKey = (finding.control && finding.control.key) || payload.controlKey;
const rule = rulesets
  .flatMap((ruleset) => ruleset.rules || [])
  .find((candidate) => candidate.key === controlKey);

if (!rule || !rule.hasRemediation) {
  return [
    {
      json: {
        propose: false,
        findingId,
        organisationId: event.organisationId,
        correlationId: event.correlationId,
        severity: finding.severity,
        reason:
          'The rule that raised this finding declares no automated remediation. It is recorded ' +
          'for a person to act on.',
      },
    },
  ];
}

// The ruleset lists a remediation, but this deployment may have no connector
// able to perform it. Proposing something that cannot execute would be noise.
const capability = capabilities.find((candidate) =>
  rulesets.some((ruleset) =>
    (ruleset.rules || []).some((r) => r.key === controlKey && candidate.actionType),
  ),
);

return [
  {
    json: {
      propose: Boolean(capability),
      findingId,
      organisationId: event.organisationId,
      correlationId: event.correlationId,
      controlKey,
      severity: finding.severity,
      title: finding.title,
      description: finding.description,
      actionType: capability ? capability.actionType : null,
      riskClass: capability ? capability.riskClass : null,
      reason: capability
        ? 'A connector in this deployment can perform the remediation the rule specifies.'
        : 'The rule specifies a remediation but no connector in this deployment can perform it.',
    },
  },
];

/**
 * No automated remediation. Say so plainly rather than staying silent.
 *
 * A finding nobody is told about is worse than one with no automated fix.
 */
const input = $input.first().json;
return [
  {
    json: {
      organisationId: input.organisationId,
      correlationId: input.correlationId,
      severity: input.severity === 'CRITICAL' || input.severity === 'HIGH' ? 'urgent' : 'info',
      subject: 'Adericel finding needs a person: ' + (input.title || input.findingId),
      message:
        (input.description || '') + '\n\n' + input.reason +
        '\n\nThis finding is recorded and will keep ageing from its first detection until it is ' +
        'resolved or an exception is authorised.',
    },
  },
];

/**
 * Assemble the proposal, including a stable idempotency key.
 *
 * The key is derived from what the action would do — its type, its target and
 * the finding behind it. Two workflows reacting to the same finding therefore
 * converge on one action instead of dispatching two changes to the same
 * customer system.
 */
const input = $input.first().json;
const crypto = require('crypto');

if (!input.actionType || !input.organisationId) {
  throw new Error('A proposal needs at least an organisationId and an actionType.');
}

const idempotencyKey =
  'act-' +
  crypto
    .createHash('sha256')
    .update(
      [
        input.organisationId,
        input.actionType,
        input.targetExternalId || input.targetNodeId || '',
        input.findingId || '',
      ].join('|'),
    )
    .digest('hex')
    .slice(0, 40);

return [
  {
    json: {
      organisationId: input.organisationId,
      correlationId: input.correlationId || $execution.id,
      apiBaseUrl: $('Configuration').first().json.apiBaseUrl,
      idempotencyKey,
      proposal: {
        actionType: input.actionType,
        integrationId: input.integrationId || null,
        targetNodeId: input.targetNodeId || null,
        targetExternalId: input.targetExternalId || null,
        parameters: input.parameters || {},
        findingId: input.findingId || null,
        rationale:
          input.rationale ||
          'Proposed automatically by the Adericel remediation workflow in response to finding ' +
            (input.findingId || 'unknown') + '.',
        idempotencyKey,
      },
    },
  },
];

/**
 * The action is waiting on a person. Nothing further happens here.
 *
 * Adericel has already published ActionApprovalRequested, which the approval
 * workflow picks up. This branch exists so the proposal workflow ends in a
 * clearly described state rather than appearing to have done nothing.
 */
const response = $input.first().json.body || {};
return [
  {
    json: {
      actionId: response.action && response.action.id,
      state: response.action && response.action.state,
      requiredApprovals: response.decision && response.decision.requiredApprovals,
      reason: response.decision && response.decision.reason,
      outcome: 'awaiting-approval',
    },
  },
];

/**
 * Policy refused. That is a legitimate, common outcome and it is reported.
 *
 * A denied action is not a failure of the workflow — it is the policy engine
 * doing its job. The reason is surfaced so an operator can decide whether the
 * policy is wrong or the proposal was.
 */
const response = $input.first().json.body || {};
const decision = response.decision || {};
const trigger = $('When called by another workflow').first().json;

return [
  {
    json: {
      organisationId: trigger.organisationId,
      correlationId: trigger.correlationId,
      severity: 'info',
      subject: 'Adericel: remediation denied by policy',
      message:
        'A remediation was proposed and refused by policy. ' + (decision.reason || '') +
        (decision.matchedRuleId ? ' (policy rule: ' + decision.matchedRuleId + ')' : '') +
        ' The finding remains open and is recorded for a person to address.',
      outcome: 'denied',
    },
  },
];

/**
 * Give the approver what they need to decide, not just a link.
 *
 * The policy decision is included in full — which rule matched, the effective
 * autonomy level, the checks that ran — because an approver asked to authorise
 * a change to a customer's environment deserves to see why the system thinks it
 * is permissible.
 */
const action = $input.first().json.body || {};
const event = $('When called by another workflow').first().json;
const decision = action.policyDecision || {};
const checks = (decision.evaluation || [])
  .map((check) => '  - ' + check.check + ': ' + check.detail)
  .join('\n');

const message =
  'Adericel is asking permission to make a change in a customer environment.\n\n' +
  'Action: ' + action.actionType + '\n' +
  'Target: ' + (action.target || 'not specified') + '\n' +
  'Risk class: ' + action.riskClass + '\n' +
  'Effective autonomy: L' + (action.autonomyLevel != null ? action.autonomyLevel : '?') + '\n\n' +
  'Why it is proposed:\n' + (action.rationale || 'No rationale recorded.') + '\n\n' +
  'What policy decided:\n' + (decision.reason || 'No decision recorded.') + '\n' +
  (checks ? checks + '\n' : '') +
  '\nNothing has been dispatched. It will not run until a person other than the proposer approves it' +
  (event.payload && event.payload.expiresAt
    ? ', and the request expires at ' + event.payload.expiresAt + '.'
    : '.');

return [
  {
    json: {
      organisationId: event.organisationId,
      correlationId: event.correlationId,
      actionId: action.id,
      severity: action.riskClass === 'DISRUPTIVE' || action.riskClass === 'DESTRUCTIVE' ? 'urgent' : 'attention',
      subject: 'Adericel needs approval: ' + action.actionType,
      message,
      requiresHumanDecision: true,
    },
  },
];

/**
 * Work out which action to execute, whichever path called us.
 *
 * This workflow is reached either from an ActionApproved event or directly from
 * the proposal workflow when policy authorised the action outright, and those
 * two shapes differ.
 */
const input = $input.first().json;

const actionId =
  input.subjectId ||
  input.actionId ||
  (input.body && input.body.action && input.body.action.id);

const organisationId = input.organisationId || (input.body && input.body.organisationId);

if (!actionId || !organisationId) {
  throw new Error('Cannot determine which action to execute; refusing to guess.');
}

return [
  {
    json: {
      actionId,
      organisationId,
      correlationId: input.correlationId || $execution.id,
      apiBaseUrl: $('Configuration').first().json.apiBaseUrl,
    },
  },
];

/**
 * A previous attempt had an unknown outcome.
 *
 * This is the most dangerous state in the whole system: Adericel dispatched
 * something and never learned whether it took effect. Retrying could duplicate
 * a change in a customer's environment, so it is escalated to a person instead
 * of being resolved automatically.
 */
const input = $input.first().json;
const resolved = $('Resolve the action').first().json;

return [
  {
    json: {
      organisationId: resolved.organisationId,
      correlationId: resolved.correlationId,
      severity: 'urgent',
      subject: 'Adericel: an action needs manual reconciliation',
      message:
        'Action ' + resolved.actionId + ' has a previous execution attempt whose outcome is ' +
        'unknown. Adericel will not retry it, because a retry could duplicate a change in the ' +
        "customer's environment.\n\n" +
        'Check the target system to determine whether the change took effect, then resolve the ' +
        'action in Adericel.\n\n' +
        'API response: ' + JSON.stringify(input.body || {}),
    },
  },
];

/**
 * The action failed outright. That is a clean outcome: nothing changed.
 */
const input = $input.first().json;
const resolved = $('Resolve the action').first().json;
const body = input.body || {};

return [
  {
    json: {
      organisationId: resolved.organisationId,
      correlationId: resolved.correlationId,
      severity: 'attention',
      subject: 'Adericel: remediation failed',
      message:
        'Action ' + resolved.actionId + ' did not complete. ' +
        (body.detail || 'No detail was returned.') +
        '\n\nThe finding remains open and the customer environment is unchanged.',
    },
  },
];

const input = $input.first().json;
const actionId =
  input.subjectId || input.actionId || (input.body && input.body.actionId);
const organisationId = input.organisationId;

if (!actionId || !organisationId) {
  throw new Error('Cannot determine which action to verify; refusing to guess.');
}

return [
  {
    json: {
      actionId,
      organisationId,
      correlationId: input.correlationId || $execution.id,
      apiBaseUrl: $('Configuration').first().json.apiBaseUrl,
    },
  },
];

/**
 * The change did not take effect, despite the execution reporting success.
 *
 * This is exactly why verification exists. Reporting the execution as
 * successful here would have left the customer with an unfixed problem that
 * Adericel believed was fixed — which is worse than never having tried.
 */
const body = $input.first().json.body || {};
const resolved = $('Resolve the action').first().json;

return [
  {
    json: {
      organisationId: resolved.organisationId,
      correlationId: resolved.correlationId,
      severity: 'urgent',
      subject: 'Adericel: a remediation did not take effect',
      message:
        'Action ' + resolved.actionId + ' reported success, but re-observing the source shows the ' +
        'intended change is not in place.\n\n' + (body.detail || '') +
        '\n\nThe action is marked for rollback and the finding remains open. Do not assume the ' +
        'problem is fixed.',
    },
  },
];

/**
 * Adericel cannot tell whether the change took effect.
 *
 * The action stays UNVERIFIED. It is not recorded as successful, and the
 * control it was meant to fix will report on the evidence actually available —
 * which may well still be UNKNOWN.
 */
const body = $input.first().json.body || {};
const resolved = $('Resolve the action').first().json;

return [
  {
    json: {
      organisationId: resolved.organisationId,
      correlationId: resolved.correlationId,
      severity: 'attention',
      subject: 'Adericel: a remediation could not be verified',
      message:
        'Action ' + resolved.actionId + ' was dispatched but Adericel cannot confirm it achieved ' +
        'the intended state.\n\n' + (body.detail || '') +
        '\n\nThe action is recorded as UNVERIFIED — not as successful. Check the target system ' +
        'directly, or restore collection so Adericel can see it.',
    },
  },
];

/**
 * Structural validation before anything is forwarded.
 *
 * Adericel validates again on receipt — this is not a substitute for that. It
 * exists so a malformed batch fails here with a clear message rather than
 * producing a partial ingest that is harder to reason about afterwards.
 */
const body = $input.first().json.body || {};
const observations = body.observations;

if (!body.organisationId || !/^[0-9a-f-]{36}$/i.test(String(body.organisationId))) {
  throw new Error('organisationId is missing or is not a UUID.');
}
if (!Array.isArray(observations) || observations.length === 0) {
  throw new Error('observations must be a non-empty array.');
}
if (observations.length > 1000) {
  throw new Error('Batches are limited to 1000 observations. Split the batch and retry.');
}

for (const [index, observation] of observations.entries()) {
  if (!observation.kind) throw new Error('Observation ' + index + ' has no kind.');
  if (!observation.sourceSystem) throw new Error('Observation ' + index + ' has no sourceSystem.');
  if (!observation.payload || typeof observation.payload !== 'object') {
    throw new Error('Observation ' + index + ' has no payload object.');
  }
}

return [
  {
    json: {
      organisationId: body.organisationId,
      integrationId: body.integrationId || null,
      observations,
      count: observations.length,
      apiBaseUrl: $('Configuration').first().json.apiBaseUrl,
      correlationId: body.correlationId || $execution.id,
    },
  },
];

