parameters.jsCode:
/**
 * Shape whatever the extraction step produced into candidate claims.
 *
 * Three properties are enforced here regardless of what the model returned:
 *
 *  - origin is AI_SUGGESTED and status is CANDIDATE, so the Truth Engine will
 *    not consume them;
 *  - extractionConfidence describes the extraction only. It is never an
 *    assurance probability, and Adericel has no path that turns it into one;
 *  - every claim cites the evidence it came from, so a human confirming it can
 *    see the document.
 */
const evidenceResponse = $('Record document as evidence').first().json;
const evidenceId = evidenceResponse.body && evidenceResponse.body.id;
if (!evidenceId) {
  throw new Error('The document was not recorded as evidence; refusing to derive claims from nothing.');
}

const extracted = $input.first().json.extractedClaims || [];

return extracted
  .filter((claim) => claim && claim.predicate)
  .map((claim) => ({
    json: {
      predicate: claim.predicate,
      subjectNodeId: claim.subjectNodeId || null,
      value: claim.value,
      origin: 'AI_SUGGESTED',
      status: 'CANDIDATE',
      extractionConfidence:
        typeof claim.confidence === 'number' ? Math.min(1, Math.max(0, claim.confidence)) : null,
      evidenceIds: [evidenceId],
      metadata: {
        extractedBy: 'n8n-document-processing',
        model: $env.ADERICEL_AI_MODEL || 'unspecified',
        requiresHumanConfirmation: true,
      },
    },
  }));

/**
 * Tell a human there is something to confirm.
 *
 * The message deliberately says what the claims are NOT: they are candidates,
 * they are not influencing any assurance state, and they will not until someone
 * reviews them.
 */
const items = $input.all();
const trigger = $('When called by another workflow').first().json;
const accepted = items.filter((item) => item.json.statusCode && item.json.statusCode < 300).length;

return [
  {
    json: {
      organisationId: trigger.organisationId,
      correlationId: trigger.correlationId,
      subject: 'Document processed — ' + accepted + ' claim(s) awaiting human confirmation',
      severity: 'info',
      message:
        'The document was stored as evidence. ' + accepted + ' claim(s) were extracted by AI and ' +
        'recorded as candidates. They are NOT influencing any assurance state and will not until ' +
        'a person confirms them. Review them in the organisation claims view.',
    },
  },
];

/**
 * Map vendor field names onto Adericel's canonical observation payload.
 *
 * The single most important rule: an absent source field produces an absent
 * canonical field. It is never defaulted. A missing fact must reach the Truth
 * Engine as missing so the control reports UNKNOWN — defaulting it here would
 * turn "we do not know" into "it is fine", which is the exact failure mode
 * Adericel exists to prevent.
 */
const input = $input.first().json;
const records = input.records || [];
const mapping = input.mapping || {};
const kind = input.kind || 'CONFIGURATION_SETTING';

function pluck(source, path) {
  return String(path)
    .split('.')
    .reduce((current, segment) => (current == null ? undefined : current[segment]), source);
}

const observations = records.map((record) => {
  const payload = {};
  for (const [canonicalField, sourcePath] of Object.entries(mapping)) {
    const value = pluck(record, sourcePath);
    if (value !== undefined && value !== null) {
      payload[canonicalField] = value;
    }
  }
  return {
    kind,
    sourceSystem: input.sourceSystem,
    subjectExternalId: payload.externalId ? String(payload.externalId) : null,
    observedAt: input.observedAt || new Date().toISOString(),
    payload,
  };
});

return [
  {
    json: {
      organisationId: input.organisationId,
      integrationId: input.integrationId || null,
      correlationId: input.correlationId || $execution.id,
      observations,
      apiBaseUrl: $('Configuration').first().json.apiBaseUrl,
    },
  },
];

/**
 * Decide what to collect on day one.
 *
 * An organisation with no sources is a legitimate state: every control needing
 * collected evidence will be UNKNOWN until one is connected. That is reported
 * rather than hidden, because it is the single most useful thing an MSP can
 * learn on the first day.
 */
const response = $input.first().json;
const integrations = (response.body && response.body.integrations) || [];
const trigger = $('When called by another workflow').first().json;
const apiBaseUrl = $('Configuration').first().json.apiBaseUrl;

const base = {
  organisationId: trigger.organisationId,
  correlationId: trigger.correlationId,
  apiBaseUrl,
};

const usable = integrations.filter((integration) => integration.status !== 'DISABLED');

if (usable.length === 0) {
  return [
    {
      json: {
        ...base,
        note:
          'No sources are connected. Every control requiring collected evidence will report ' +
          'UNKNOWN until at least one integration is configured.',
      },
    },
  ];
}

return usable.map((integration) => ({
  json: {
    ...base,
    integrationId: integration.id,
    connectorKey: integration.connectorKey,
    name: integration.name,
  },
}));

/**
 * Report the day-one picture in terms an MSP can act on.
 *
 * Coverage is stated as a count with its denominator. There is deliberately no
 * score: a customer at full satisfaction over eight per cent coverage is not in
 * good shape, and a single number would say otherwise.
 */
const assurance = $input.first().json.body || {};
const counts = assurance.counts || {};
const inScope = assurance.inScope || 0;
const unknown = counts.UNKNOWN || 0;
const failing = counts.NOT_SATISFIED || 0;
const determinate = inScope - unknown;

const message =
  'Adericel can currently speak to ' + determinate + ' of ' + inScope + ' in-scope controls. ' +
  unknown + ' are UNKNOWN — not passing and not failing — because there is not yet sufficient ' +
  'trustworthy evidence. ' +
  (failing > 0 ? failing + ' control(s) are failing outright. ' : '') +
  'Connecting the remaining sources is what reduces the unknown count.';

return [
  {
    json: {
      organisationId: assurance.organisationId,
      correlationId: $('When called by another workflow').first().json.correlationId,
      subject: 'Adericel onboarding complete',
      severity: unknown > determinate ? 'attention' : 'info',
      message,
      counts,
      inScope,
    },
  },
];

const response = $input.first().json.body || {};
const config = $('Configuration').first().json;
return (response.organisations || []).map((organisation) => ({
  json: {
    organisationId: organisation.id,
    organisationName: organisation.name,
    apiBaseUrl: config.apiBaseUrl,
    correlationId: $execution.id + '-' + organisation.id,
  },
}));

const response = $input.first().json;
const batch = $('One organisation at a time').first().json;
const integrations = (response.body && response.body.integrations) || [];

return integrations
  .filter((integration) => ['CONFIGURED', 'CONNECTED', 'DEGRADED'].includes(integration.status))
  .map((integration) => ({
    json: {
      organisationId: batch.organisationId,
      apiBaseUrl: batch.apiBaseUrl,
      correlationId: batch.correlationId,
      integrationId: integration.id,
      name: integration.name,
    },
  }));

const response = $input.first().json.body || {};
const config = $('Configuration').first().json;
return (response.organisations || []).map((organisation) => ({
  json: {
    organisationId: organisation.id,
    apiBaseUrl: config.apiBaseUrl,
    correlationId: $execution.id + '-' + organisation.id,
  },
}));

/**
 * Identify organisations whose evidence position needs a person.
 *
 * Stale evidence and failed collection are reported together because they have
 * the same consequence — controls going Unknown — and the same owner: the MSP,
 * not the customer.
 */
const portfolio = $input.first().json.body || {};
const organisations = portfolio.organisations || [];

const needsAttention = organisations.filter(
  (organisation) =>
    organisation.staleEvidence > 0 ||
    organisation.failedIntegrations > 0 ||
    organisation.counts.UNKNOWN > 0,
);

if (needsAttention.length === 0) {
  return [{ json: { anythingToChase: false } }];
}

const lines = needsAttention.map((organisation) => {
  const parts = [];
  if (organisation.failedIntegrations > 0) {
    parts.push(organisation.failedIntegrations + ' source(s) not collecting');
  }
  if (organisation.staleEvidence > 0) {
    parts.push(organisation.staleEvidence + ' evidence record(s) past their freshness limit');
  }
  if (organisation.counts.UNKNOWN > 0) {
    parts.push(organisation.counts.UNKNOWN + ' control(s) Unknown');
  }
  return '  - ' + organisation.name + ': ' + parts.join(', ');
});

return [
  {
    json: {
      anythingToChase: true,
      correlationId: $execution.id,
      severity: 'attention',
      subject: 'Adericel: evidence needs attention across ' + needsAttention.length + ' customer(s)',
      message:
        'These customers have evidence gaps. Most are collection problems on our side rather than ' +
        'posture changes on theirs, and each one means Adericel cannot currently speak to controls ' +
        'it previously could.\n\n' + lines.join('\n') +
        '\n\nRestoring collection is what reduces the Unknown count.',
    },
  },
];

/**
 * Write the weekly report in the product's own terms.
 *
 * The structure follows what an MSP actually needs to decide on a Monday:
 * what changed, what needs a person, and where one fix would help several
 * customers at once. No score, and unknowns never folded into failures.
 */
const portfolio = $('Portfolio').first().json.body || {};
const recurring = ($('Recurring failures').first().json.body || {}).controls || [];
const deteriorating = ($('Deteriorating customers').first().json.body || {}).organisations || [];
const totals = portfolio.totals || {};
const organisations = portfolio.organisations || [];

const sections = [];

sections.push(
  'ADERICEL WEEKLY PORTFOLIO REPORT\n' +
    new Date().toISOString().slice(0, 10) + '\n' +
    organisations.length + ' organisation(s) under management',
);

sections.push(
  'POSITION\n' +
    '  Failing controls:  ' + (totals.failingControls || 0) + '\n' +
    '  Unknown controls:  ' + (totals.unknownControls || 0) + '   (Adericel cannot currently speak to these)\n' +
    '  Critical findings: ' + (totals.criticalFindings || 0) + '\n' +
    '  Open findings:     ' + (totals.openFindings || 0) + '\n' +
    '  Awaiting approval: ' + (totals.awaitingApproval || 0) + '\n' +
    '  Unverified actions:' + (totals.unverifiedActions || 0),
);

if ((totals.failedIntegrations || 0) > 0 || (totals.staleEvidence || 0) > 0) {
  sections.push(
    'OUR PROBLEMS, NOT THE CUSTOMERS\n' +
      '  Sources not collecting: ' + (totals.failedIntegrations || 0) + '\n' +
      '  Evidence past freshness: ' + (totals.staleEvidence || 0) + '\n' +
      '  These are why controls report Unknown. Restoring collection is the fix.',
  );
}

if (deteriorating.length > 0) {
  sections.push(
    'DETERIORATED THIS WEEK\n' +
      deteriorating
        .map(
          (organisation) =>
            '  - ' + organisation.name + ': ' + organisation.deteriorations +
            ' control(s) moved from proven to failing or unknown' +
            (organisation.newlyUnknown ? ' (' + organisation.newlyUnknown + ' newly unknown)' : ''),
        )
        .join('\n'),
  );
}

if (recurring.length > 0) {
  sections.push(
    'ONE FIX, SEVERAL CUSTOMERS\n' +
      recurring
        .slice(0, 5)
        .map(
          (control) =>
            '  - ' + control.title + ': affecting ' + control.affectedOrganisations + ' of ' +
            control.totalOrganisations + ' customers' +
            (control.systemicRemediation ? ' — automatable' : ' — needs a person'),
        )
        .join('\n'),
  );
}

sections.push(
  'BY CUSTOMER\n' +
    organisations
      .map((organisation) => {
        const counts = organisation.counts || {};
        const inScope =
          (counts.SATISFIED || 0) + (counts.EXCEPTED || 0) + (counts.NOT_SATISFIED || 0) +
          (counts.PARTIALLY_SATISFIED || 0) + (counts.UNKNOWN || 0);
        return (
          '  - ' + organisation.name.padEnd(30) +
          (counts.SATISFIED || 0) + ' proven of ' + inScope + ' in scope' +
          ((counts.NOT_SATISFIED || 0) > 0 ? ', ' + counts.NOT_SATISFIED + ' failing' : '') +
          ((counts.UNKNOWN || 0) > 0 ? ', ' + counts.UNKNOWN + ' unknown' : '')
        );
      })
      .join('\n'),
);

return [
  {
    json: {
      correlationId: $execution.id,
      severity: 'info',
      subject: 'Adericel weekly portfolio report',
      message: sections.join('\n\n'),
    },
  },
];

/**
 * Decide whether Adericel itself needs attention.
 *
 * An unreachable API is treated as the most serious state: if Adericel cannot
 * be reached, nothing it previously reported can be trusted to still be current,
 * and no assurance is being maintained at all.
 */
const healthResponse = $('Read health').first().json;
const outboxResponse = $input.first().json;

if (!healthResponse.statusCode || healthResponse.statusCode >= 500) {
  return [
    {
      json: {
        degraded: true,
        severity: 'urgent',
        subject: 'Adericel is unreachable',
        message:
          'The Adericel API did not respond to a health check (status ' +
          (healthResponse.statusCode || 'no response') + ').\n\n' +
          'While it is unreachable no assurance is being maintained: no evidence is being ' +
          'collected, nothing is being reassessed, and no assurance state is being updated. ' +
          'The last known state is still visible but is not current.',
        correlationId: $execution.id,
      },
    },
  ];
}

const health = healthResponse.body || {};
const outbox = outboxResponse.body || {};
const problems = health.platformProblems || [];
const unhealthy = (health.components || []).filter((component) => component.status === 'UNHEALTHY');
const degraded = (health.components || []).filter((component) => component.status === 'DEGRADED');

if (health.status === 'HEALTHY' && problems.length === 0 && outbox.healthy !== false) {
  return [{ json: { degraded: false } }];
}

const lines = [];
for (const component of unhealthy) lines.push('  UNHEALTHY  ' + component.component + ': ' + component.detail);
for (const component of degraded) lines.push('  degraded   ' + component.component + ': ' + component.detail);
for (const problem of problems) lines.push('  - ' + problem);
if (outbox.deadLetter > 0) {
  lines.push('  - ' + outbox.deadLetter + ' event(s) in the dead-letter queue; downstream views may be stale.');
}

return [
  {
    json: {
      degraded: true,
      severity: unhealthy.length > 0 ? 'urgent' : 'attention',
      subject: 'Adericel platform health: ' + health.status,
      message:
        'Adericel itself needs attention. These are platform problems, not customer assurance ' +
        'problems — but they will show up as customer Unknowns if left.\n\n' + lines.join('\n'),
      correlationId: $execution.id,
    },
  },
];

/**
 * Report a dead-letter backlog, or a delivery lag, in operational terms.
 *
 * A growing pending queue is reported as well as dead letters: an event that
 * has not been delivered yet is not lost, but it does mean everything
 * downstream of it is behind reality.
 */
const outbox = $input.first().json.body || {};
const deadLetter = outbox.deadLetter || 0;
const oldestPending = outbox.oldestPendingAgeSeconds || 0;

if (deadLetter === 0 && oldestPending < 300) {
  return [{ json: { needsAttention: false } }];
}

const lines = [];
if (deadLetter > 0) {
  lines.push(
    deadLetter + ' event(s) have exhausted their delivery attempts. Anything downstream that ' +
      'depended on them — a dashboard, a notification, a workflow — is now out of step with ' +
      "Adericel's own record. Adericel itself remains correct; the consumers do not.",
  );
}
if (oldestPending >= 300) {
  lines.push(
    'The oldest undelivered event is ' + Math.round(oldestPending / 60) + ' minute(s) old. ' +
      'Event delivery is lagging; check that the Adericel worker is running.',
  );
}

return [
  {
    json: {
      needsAttention: true,
      severity: deadLetter > 0 ? 'urgent' : 'attention',
      correlationId: $execution.id,
      subject: 'Adericel: event delivery needs attention',
      message:
        lines.join('\n\n') +
        '\n\nNothing has been replayed automatically. An event that failed repeatedly needs ' +
        'diagnosis rather than another attempt. Replay from the Adericel operations runbook once ' +
        'the cause is understood.',
    },
  },
];

const status = $input.first().json.body || {};
const blockers = status.blockers || [];
return [{
  json: {
    organisationId: status.organisationId,
    readyToClose: status.readyToClose === true,
    blockers,
    finalExportHash: status.finalExportHash,
    subject: status.readyToClose
      ? 'Offboarding complete and ready to close'
      : 'Offboarding is under way and cannot be closed yet',
    message: status.readyToClose
      ? 'Everything required has been done. The customer has their record (' +
        String(status.finalExportHash || 'no hash recorded') +
        '), assurance has stopped, shared passports no longer answer, and credentials are ' +
        'destroyed. Closing is a person\'s decision.'
      : 'Still outstanding: ' + blockers.join('; '),
    // Never CRITICAL. A customer leaving in an orderly way is not an incident,
    // and treating it as one trains people to ignore the channel.
    severity: status.readyToClose ? 'INFO' : 'MEDIUM',
  },
}];

const response = $input.first().json.body || {};
const config = $('Configuration').first().json;
return (response.organisations || []).map((organisation) => ({
  json: {
    organisationId: organisation.id,
    organisationName: organisation.name,
    apiBaseUrl: config.apiBaseUrl,
  },
}));

const conflicts = ($input.first().json.body || {}).conflicts || [];
const blocking = conflicts.filter((conflict) => conflict.blocksAssurance);
if (blocking.length === 0) return [];

const context = $('One organisation at a time').first().json;
const lines = blocking.map((conflict) => {
  const positions = (conflict.sources || [])
    .map((source) => source.name + ' says ' + JSON.stringify(source.value))
    .join(', ');
  return '- ' + conflict.predicate +
    (conflict.subjectExternalId ? ' for ' + conflict.subjectExternalId : '') +
    ': ' + positions;
});

return [{
  json: {
    organisationId: context.organisationId,
    subject: blocking.length + ' fact(s) Adericel will not assert for ' + context.organisationName,
    message:
      'Two systems disagree and nothing tells Adericel which to believe, so it will not ' +
      'choose. Every control resting on these reads Unknown until the disagreement is ' +
      'settled.\n\n' + lines.join('\n') +
      '\n\nEither correct whichever system is wrong, or name an authoritative source for ' +
      'these facts.',
    // A contested fact is a real gap in assurance, not a technical warning.
    severity: 'HIGH',
  },
}];

const response = $input.first().json.body || {};
const config = $('Configuration').first().json;
return (response.organisations || []).map((organisation) => ({
  json: {
    organisationId: organisation.id,
    organisationName: organisation.name,
    apiBaseUrl: config.apiBaseUrl,
  },
}));

const coverage = $input.first().json.body || {};
const broken = coverage.brokenCapabilities || [];
const context = $('One organisation at a time').first().json;

// Demonstration data in a live tenant is worth saying out loud on its own,
// because anything resting on it must not be shared or relied upon.
const notes = [];
if (coverage.containsDemonstrationData) {
  notes.push(
    'This organisation contains demonstration data. Nothing resting on it describes a real ' +
    'estate.',
  );
}
if (broken.length === 0 && notes.length === 0) return [];

const lines = broken.map((capability) => {
  const remedy = capability.requiredPermission
    ? ' Grant ' + capability.requiredPermission + '.'
    : '';
  const cost = (capability.unavailablePredicates || []).length;
  return '- ' + capability.integrationName + ': ' + capability.detail + remedy +
    (cost > 0 ? ' (' + cost + ' fact(s) unavailable)' : '');
});

return [{
  json: {
    organisationId: context.organisationId,
    subject: broken.length > 0
      ? broken.length + ' capability(ies) failing for ' + context.organisationName
      : 'Coverage note for ' + context.organisationName,
    message: [...notes, ...lines].join('\n') +
      '\n\nAdericel can currently supply ' + (coverage.satisfiedPredicates || 0) + ' of the ' +
      (coverage.requiredPredicates || 0) + ' facts your frameworks need.',
    severity: broken.length > 0 ? 'MEDIUM' : 'INFO',
  },
}];

const body = $input.first().json.body || {};
const runs = body.runs || [];

// Rows acted on since the last run, so a report says what actually happened
// rather than only that something happened.
const lastRunAt = body.lastRunAt;
const latest = runs.filter((run) => run.ranAt === lastRunAt);
const acted = latest.filter((run) => run.rowsAffected > 0);

const lines = acted.map((run) =>
  `- ${run.entry}: ${run.treatment.toLowerCase()} ${run.rowsAffected} row(s) older than ${run.retentionDays} days`,
);

return [{
  json: {
    overdue: body.overdue === true,
    lastRunAt: lastRunAt,
    hoursSinceLastRun: body.hoursSinceLastRun,
    periodsDeclared: (body.schedule || []).length,
    rowsActedOn: acted.reduce((total, run) => total + run.rowsAffected, 0),
    summary: lines.length > 0 ? lines.join('\n') : 'Nothing was past its retention period.',
  },
}];

const state = $input.first().json;
const hours = state.hoursSinceLastRun;

return [{
  json: {
    severity: 'HIGH',
    subject: 'The retention sweep has not run',
    body: [
      hours === null
        ? 'The retention sweep has no recorded run at all.'
        : `The retention sweep last ran ${hours} hours ago.`,
      '',
      `${state.periodsDeclared} retention periods are declared in the register and published ` +
        'in the retention schedule. While the sweep is not running, none of them is being kept.',
      '',
      'This is a data protection failure rather than an operational one: the periods are ' +
        'promised to customers in the DPA and to individuals in the privacy notice.',
      '',
      'Check the worker is running and that the sweep-retention job is enabled.',
    ].join('\n'),
  },
}];

const state = $input.first().json;
return [{
  json: {
    severity: 'INFO',
    subject: 'Retention sweep ran',
    body: `Last run ${state.lastRunAt}. ${state.rowsActedOn} row(s) acted on.\n\n${state.summary}`,
  },
}];

/**
 * Verify the delivery is genuinely from this Adericel deployment.
 *
 * The signature covers "{timestamp}.{rawBody}". The digest is compared in
 * constant time so response timing reveals nothing, and the timestamp window
 * makes a captured delivery useless after five minutes.
 */
const crypto = require('crypto');

const secret = $env.ADERICEL_WEBHOOK_SECRET;
if (!secret) {
  throw new Error(
    'ADERICEL_WEBHOOK_SECRET is not set on this n8n instance. Refusing to accept unauthenticated events.',
  );
}

const item = $input.first();
const headers = item.json.headers ?? {};
const signature = headers['x-adericel-signature'];
const timestamp = headers['x-adericel-timestamp'];
const rawBody = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(item.json.body ?? {});

if (!signature || !timestamp) {
  throw new Error('Delivery is missing its signature or timestamp headers.');
}

const ageMs = Math.abs(Date.now() - Number(timestamp));
if (!Number.isFinite(ageMs) || ageMs > 300000) {
  throw new Error('Delivery timestamp is outside the five minute window; treating it as a replay.');
}

const expected = crypto
  .createHmac('sha256', secret)
  .update(timestamp + '.' + rawBody)
  .digest('hex');

const provided = Buffer.from(String(signature), 'utf8');
const computed = Buffer.from(expected, 'utf8');
const valid = provided.length === computed.length && crypto.timingSafeEqual(provided, computed);

if (!valid) {
  throw new Error('Signature verification failed. This delivery is not from the configured Adericel deployment.');
}

const event = item.json.body ?? {};
const config = $('Configuration').first().json;

return [
  {
    json: {
      ...event,
      apiBaseUrl: config.apiBaseUrl,
      notifyEmail: config.notifyEmail,
      notifyWebhookUrl: config.notifyWebhookUrl,
      mspId: config.mspId,
      verifiedAt: new Date().toISOString(),
    },
  },
];
